perl -0777 -pi -e 's/\@Entity\(tableName = "quotation"\)\s*data class Quotation\(.*?\@Entity\(\s*tableName = "quotation_item",\s*indices = \[Index\("quotationId"\)\]\s*\)\s*data class QuotationItem\(.*?\)\n/\@Entity\(tableName = "quotation"\)\ndata class Quotation\(\n    \@PrimaryKey\(autoGenerate = true\) val id: Int = 0,\n    val quotationNumber: String = "",\n    val date: Long = 0L,\n    val customerId: Long = 0L,\n    val customerName: String = "",\n    val customerPhone: String = "",\n    val customerAddress: String = "",\n    val projectType: String = "",\n    val category: String = "",\n    val material: String = "",\n    val finish: String = "",\n    val subtotal: Double = 0\.0,\n    val discount: Double = 0\.0,\n    val gstRate: Double = 0\.0,\n    val gstAmount: Double = 0\.0,\n    val grandTotal: Double = 0\.0,\n    val termsAndConditions: String = "",\n    val warranty: String = "",\n    val status: String = "DRAFT"\n\)\n\n\@Entity\(\n    tableName = "quotation_item",\n    indices = \[Index\("quotationId"\)\]\n\)\ndata class QuotationItem\(\n    \@PrimaryKey\(autoGenerate = true\) val id: Int = 0,\n    val quotationId: Int,\n    val itemName: String = "",\n    val description: String = "",\n    val material: String = "",\n    val finish: String = "",\n    val quantity: Double,\n    val unit: String,\n    val rate: Double,\n    val amount: Double\n\)\n/s' app/src/main/java/com/example/data/Entities.kt
